window.kbPageData["views/entry/k-73e198d9883a03d3"] = {"key":"entry/k-73e198d9883a03d3","state":{"route":"entry/k-73e198d9883a03d3"},"node":{"id":"k-73e198d9883a03d3","mode":"k","title":"溶液混合的线段法","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两种溶液混合时，原溶液质量与各自浓度到混合浓度的差值成反比"],"qs":["江苏 2023 B类 行测#64"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"将两种质量分数不同的同种溶质溶液混合，若溶质和溶液的总质量均守恒，两种原溶液的质量之比等于各自浓度与混合浓度之差的绝对值的反比。","review":{"definition":"将两种质量分数不同的同种溶质溶液混合，若溶质和溶液的总质量均守恒，两种原溶液的质量之比等于各自浓度与混合浓度之差的绝对值的反比。","explanation":"以混合浓度为基准，低浓度溶液的溶质差额等于高浓度溶液的溶质盈余，因此两边的溶液质量与对应浓度差的乘积相等。本题先把72%和78%的两份溶液视为一份76%的混合液。68%溶液与76%混合液配成74%，质量比为(76%−74%)∶(74%−68%)＝1∶3，因此76%混合液有180克。再按(78%−76%)∶(76%−72%)＝1∶2拆分，72%溶液占180克的三分之一，即60克，对应D项。","references":[],"evidence":"浓度之差与酒精溶液质量成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#64":{"paper":"江苏 2023 B类 行测","n":64,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",11],"asrc":["b08f2713d73015eac675.pdf",20],"card":"405c6249d5c6a099c4988949","links":[{"id":"k-73e198d9883a03d3","role":"解题依据","why":"该关系可分别确定两组混合的质量比，再由总质量反推目标溶液的质量。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-73e198d9883a03d3":[["江苏 2023 B类 行测#64"]]}};
